import { describe, it, expect } from "vitest";
import { parseGcodeText, resolveGcode, type GcodeResult } from "../lib/engine/index";
import { describeGcode, gcodeStatusFor } from "./PublicQuotePage.svelte";

// A slicer that reports weight but no print time must not be styled as green success: hasExactParse
// would hide the manual time inputs and leave Submit stuck disabled.
describe("PublicQuotePage: describeGcode / gcodeStatusFor", () => {
  function weightOnlyResult(): GcodeResult {
    const gcodeText = [
      "; generated by PrusaSlicer 2.7.0",
      "; total filament weight [g] = 12.34",
      "; no time comment in this file",
      "G28",
    ].join("\n");
    return resolveGcode(parseGcodeText(gcodeText), 1.75, 1.24);
  }

  it("reproduces the claim: resolveGcode reports status ok with weightG set and timeSeconds undefined", () => {
    const result = weightOnlyResult();
    expect(result.status).toBe("ok");
    expect(result.weightG).toBeDefined();
    expect(result.timeSeconds).toBeUndefined();
  });

  it("describeGcode names the missing print time instead of claiming success", () => {
    const result = weightOnlyResult();
    const msg = describeGcode(result, "part.gcode");
    expect(msg).toBe("part.gcode: weight found, but no print time in the file. Enter the print time below, or remove the file.");
    expect(msg).not.toBe("part.gcode: parsed.");
  });

  it("gcodeStatusFor downgrades this case to a non-ok status", () => {
    const result = weightOnlyResult();
    expect(gcodeStatusFor(result)).toBe("incomplete");
    expect(gcodeStatusFor(result)).not.toBe("ok");
  });

  it("a fully parsed result (weight and time) is unaffected -- still 'ok' / 'parsed.'", () => {
    const gcodeText = [
      "; generated by PrusaSlicer 2.7.0",
      "; total filament weight [g] = 12.34",
      "; estimated printing time (normal mode) = 1h 2m 3s",
      "G28",
    ].join("\n");
    const result = resolveGcode(parseGcodeText(gcodeText), 1.75, 1.24);
    expect(result.timeSeconds).toBeDefined();
    expect(gcodeStatusFor(result)).toBe("ok");
    expect(describeGcode(result, "part.gcode")).toBe("part.gcode: parsed.");
  });

  it("the pre-existing mirror case (time found, no weight) is untouched", () => {
    // A length with no diameter exercises the invalid-profile branch.
    const gcodeText = ["; Filament used: 3.456m", "G28"].join("\n");
    const result = resolveGcode(parseGcodeText(gcodeText), 0, 0); // invalid diameter/density
    expect(result.status).toBe("invalid-profile");
    expect(gcodeStatusFor(result)).toBe("invalid-profile");
    expect(describeGcode(result, "part.gcode")).toContain("weight couldn't be derived");
  });
});
